import { Resource, InjectionToken, Provider } from '@angular/core';

/**
 * @experimental
 */
type ResourceExtension<R extends Resource<unknown>> = {
    type: symbol;
    apply: (resource: R) => void;
};

/**
 * @experimental
 * @description
 *
 * Applies extensions to a resource and returns it with its original type
 * preserved.
 *
 * Extensions registered for the current injector scope via
 * `provideResourceExtensions` are applied first, followed by the extensions
 * passed as arguments. When multiple extensions share the same `type`, the
 * last one wins.
 *
 * @usageNotes
 *
 * ```ts
 * import { Component } from '@angular/core';
 * import { httpResource } from '@angular/common/http';
 * import {
 *   extendResource,
 *   withPreviousValueOnLoading,
 *   withValueOnError,
 * } from '@ngrx/signals/resource';
 *
 * \@Component({
 *   // ...
 * })
 * export class TodoList {
 *   readonly todosResource = extendResource(
 *     httpResource<Todo[]>(() => `/api/todos`),
 *     withPreviousValueOnLoading(),
 *     withValueOnError(undefined)
 *   );
 * }
 * ```
 *
 * When global extensions are registered, passing the resource alone is enough
 * to apply them:
 *
 * ```ts
 * readonly todosResource = extendResource(
 *   httpResource<Todo[]>(() => `/api/todos`)
 * );
 * ```
 */
declare function extendResource<R extends Resource<unknown>>(resource: R, ...extensions: ResourceExtension<NoInfer<R>>[]): R;

/**
 * @experimental
 * @description
 *
 * Extension type shared by all extensions that customize the resource value
 * while it is loading. Custom loading extensions can reuse it so that only the
 * last one takes effect.
 */
declare const LOADING_EXTENSION_TYPE: unique symbol;
/**
 * @experimental
 * @description
 *
 * Extension type shared by all extensions that customize the resource value
 * when it enters the error state. Custom error extensions can reuse it so that
 * only the last one takes effect.
 */
declare const ERROR_EXTENSION_TYPE: unique symbol;

/**
 * @experimental
 * @description
 *
 * Injection token that holds the resource extensions registered for the
 * current injector scope via `provideResourceExtensions`.
 */
declare const RESOURCE_EXTENSIONS: InjectionToken<ResourceExtension<Resource<unknown>>[]>;
/**
 * @experimental
 * @description
 *
 * Registers resource extensions for a given injector scope (application,
 * route, or component). Any resource wrapped with `extendResource` within
 * that scope automatically has these extensions applied.
 *
 * The provider is scope-aware and composes with extensions registered by
 * parent injectors, so defaults can be layered at the application level and
 * refined at the route or component level without discarding the parent
 * configuration.
 *
 * @usageNotes
 *
 * ```ts
 * import { bootstrapApplication } from '@angular/platform-browser';
 * import {
 *   provideResourceExtensions,
 *   withValueOnError,
 * } from '@ngrx/signals/resource';
 *
 * bootstrapApplication(App, {
 *   providers: [provideResourceExtensions(withValueOnError(undefined))],
 * });
 * ```
 */
declare function provideResourceExtensions(...extensions: ResourceExtension<Resource<unknown>>[]): Provider;

/**
 * @experimental
 * @description
 *
 * Creates a resource extension that returns the last successfully resolved
 * value when the resource enters the error state, instead of throwing when
 * `value()` is read.
 *
 * @usageNotes
 *
 * ```ts
 * import { httpResource } from '@angular/common/http';
 * import {
 *   extendResource,
 *   withPreviousValueOnError,
 * } from '@ngrx/signals/resource';
 *
 * const todosResource = extendResource(
 *   httpResource<Todo[]>(() => `/api/todos`),
 *   withPreviousValueOnError()
 * );
 *
 * // If the request fails, `value()` returns whatever was successfully loaded
 * // before, rather than throwing an error.
 * ```
 */
declare function withPreviousValueOnError<R extends Resource<unknown>>(): ResourceExtension<R>;

/**
 * @experimental
 * @description
 *
 * Creates a resource extension that keeps the last resolved value while the
 * resource is reloading, instead of resetting `value()` to `undefined`.
 *
 * @usageNotes
 *
 * ```ts
 * import { httpResource } from '@angular/common/http';
 * import {
 *   extendResource,
 *   withPreviousValueOnLoading,
 * } from '@ngrx/signals/resource';
 *
 * const todosResource = extendResource(
 *   httpResource<Todo[]>(() => `/api/todos?page=${this.page()}`),
 *   withPreviousValueOnLoading()
 * );
 *
 * // `value()` returns the previous page's data while the next page is loading,
 * // rather than `undefined`.
 * ```
 */
declare function withPreviousValueOnLoading<R extends Resource<unknown>>(): ResourceExtension<R>;

/**
 * @experimental
 * @description
 *
 * Creates a resource extension that returns a specific fallback value when the
 * resource enters the error state, instead of throwing when `value()` is read.
 *
 * @usageNotes
 *
 * ```ts
 * import { httpResource } from '@angular/common/http';
 * import { extendResource, withValueOnError } from '@ngrx/signals/resource';
 *
 * const todosResource = extendResource(
 *   httpResource<Todo[]>(() => `/api/todos`),
 *   withValueOnError([])
 * );
 *
 * // If the request fails, `value()` returns `[]` instead of throwing.
 * ```
 */
declare function withValueOnError<R extends Resource<unknown>>(value: R extends Resource<infer V> ? V : never): ResourceExtension<R>;

/**
 * @experimental
 * @description
 *
 * Creates a resource extension that returns a specific fallback value while
 * the resource is loading, instead of resetting `value()` to `undefined`.
 *
 * @usageNotes
 *
 * ```ts
 * import { httpResource } from '@angular/common/http';
 * import { extendResource, withValueOnLoading } from '@ngrx/signals/resource';
 *
 * const todosResource = extendResource(
 *   httpResource<Todo[]>(() => `/api/todos`),
 *   withValueOnLoading([])
 * );
 *
 * // `value()` returns `[]` on initial load and on every subsequent reload.
 * ```
 */
declare function withValueOnLoading<R extends Resource<unknown>>(value: R extends Resource<infer V> ? V : never): ResourceExtension<R>;

export { ERROR_EXTENSION_TYPE, LOADING_EXTENSION_TYPE, RESOURCE_EXTENSIONS, extendResource, provideResourceExtensions, withPreviousValueOnError, withPreviousValueOnLoading, withValueOnError, withValueOnLoading };
export type { ResourceExtension };
